class PageUtil:
    def __init__(self, data, page_size):
        self._data = data
        self._page_size = page_size
        self.total_items = len(data)
        self.total_pages = (self.total_items + self.page_size - 1) // page_size

    @property
    def data(self):
        return self._data

    @data.setter
    def data(self, value):
        self._data = value
        self.total_items = len(value)
        self.total_pages = (self.total_items + self.page_size - 1) // self.page_size

    @property
    def page_size(self):
        return self._page_size

    @page_size.setter
    def page_size(self, value):
        self._page_size = value
        self.total_pages = (self.total_items + self.page_size - 1) // self.page_size

    def get_page(self, page_number):
        if not self._is_valid_page(page_number):
            return []

        start_index = self._calculate_start_index(page_number)
        end_index = start_index + self.page_size
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        if not self._is_valid_page(page_number):
            return {}

        start_index = self._calculate_start_index(page_number)
        end_index = min(start_index + self.page_size, self.total_items)
        page_data = self.data[start_index:end_index]

        return {
            "current_page": page_number,
            "per_page": self.page_size,
            "total_pages": self.total_pages,
            "total_items": self.total_items,
            "has_previous": self._has_previous(page_number),
            "has_next": self._has_next(page_number),
            "data": page_data
        }

    def search(self, keyword):
        results = self._filter_by_keyword(keyword)
        return {
            "keyword": keyword,
            "total_results": self._count_results(results),
            "total_pages": self._calculate_total_pages(len(results)),
            "results": results
        }

    def _is_valid_page(self, page_number):
        return 1 <= page_number <= self.total_pages

    def _calculate_start_index(self, page_number):
        return (page_number - 1) * self.page_size

    def _has_previous(self, page_number):
        return page_number > 1

    def _has_next(self, page_number):
        return page_number < self.total_pages

    def _filter_by_keyword(self, keyword):
        return [item for item in self.data if keyword in str(item)]

    def _count_results(self, results):
        return len(results)

    def _calculate_total_pages(self, total_items):
        return (total_items + self.page_size - 1) // self.page_size
